const views={"flip-panels":View1};
export interface ArtemisNotFoundPagesProps{className?:string;variant?:"flip-panels";}
export function ArtemisNotFoundPages({className,variant="flip-panels"}:ArtemisNotFoundPagesProps){const View=views[variant];return <ArtemisScope className={["art:min-h-dvh art:[&>section]:min-h-dvh",className].filter(Boolean).join(" ")}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
export default function NotFoundPagesFlipPanels() {
    const reduce = useReducedMotion();
    const [shown, setShown] = useState(false);
    useEffect(() => {
        if (reduce) {
            setShown(true);
            return;
        }
        const timer = setTimeout(() => setShown(true), 80);
        return () => clearTimeout(timer);
    }, [reduce]);
    const panel = (delay: number) => ({
        initial: { opacity: 0, transform: "rotateX(-82deg)" },
        animate: shown ? { opacity: 1, transform: "rotateX(0deg)" } : undefined,
        whileHover: reduce ? undefined : { transform: "rotateX(-8deg)" },
        transition: reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay },
    });
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    return (<>
      <section className="art:flex art:min-h-[680px] art:w-full art:flex-col art:overflow-hidden art:bg-background art:text-foreground art:[container-type:inline-size]">
        <header className="art:flex art:min-h-20 art:items-center art:justify-between art:px-5 art:@min-[640px]/artemis:px-8">
          <a href="/" className="art:font-medium art:text-sm art:focus-visible:outline-2 art:focus-visible:outline-ring">
            {"Home"}
          </a>
          <span className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.18em]">
            {"Page missing"}
          </span>
        </header>
        <div className="art:flex art:flex-1 art:flex-col art:items-center art:justify-center art:px-5 art:py-10 art:text-center">
          <div className="art:flex art:w-full art:max-w-5xl art:justify-center art:gap-[1.4cqw] art:[perspective:1200px]">
            <motion.div {...panel(0)} className="art:grid art:aspect-[0.72] art:w-[25cqw] art:max-w-64 art:place-items-center art:border art:border-border art:bg-secondary art:[transform-style:preserve-3d]">
              <span className="art:font-semibold art:text-9xl art:leading-none art:tracking-[-0.09em]">
                {"4"}
              </span>
            </motion.div>
            <motion.div {...panel(0.06)} className="art:grid art:aspect-[0.72] art:w-[25cqw] art:max-w-64 art:place-items-center art:border art:border-border art:bg-secondary art:[transform-style:preserve-3d]">
              <span className="art:font-semibold art:text-9xl art:leading-none art:tracking-[-0.09em]">
                {"0"}
              </span>
            </motion.div>
            <motion.div {...panel(0.12)} className="art:grid art:aspect-[0.72] art:w-[25cqw] art:max-w-64 art:place-items-center art:border art:border-border art:bg-secondary art:[transform-style:preserve-3d]">
              <span className="art:font-semibold art:text-9xl art:leading-none art:tracking-[-0.09em]">
                {"4"}
              </span>
            </motion.div>
          </div>
          <motion.h1 initial={{ opacity: 0, y: 8 }} animate={shown ? { opacity: 1, y: 0 } : undefined} transition={reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: 0.18 }} className="art:mt-7 art:tracking-[-0.03em] art:text-4xl art:@min-[768px]/artemis:text-5xl art:font-medium">
            {"Nothing on this side."}
          </motion.h1>
          <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:h-9 art:rounded-full" href="/" tabIndex={0}>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-left art:size-4" aria-hidden="true">
              <path d="m12 19-7-7 7-7"/>
              <path d="M19 12H5"/>
            </svg>
            {"Go home"}
          </motion.a>
        </div>
      </section>
    </>);
}
